def eventualSafeNodes(V, adj):
    def dfs(node):
        if visited[node] == 1:
            return False
        if visited[node] == 2:
            return True
        visited[node] = 1
        for neighbor in adj[node]:
            if not dfs(neighbor):
                return False
        visited[node] = 2
        return True

    visited = [0] * V
    safe_nodes = []
    for i in range(V):
        if dfs(i):
            safe_nodes.append(i)
    return sorted(safe_nodes)

# Example usage:
